using System.IO; using Microsoft.EntityFrameworkCore; using LibraryManager.Models;
namespace LibraryManager.Data; public class LibraryDbContext:DbContext { public DbSet<Book> Books=>Set<Book>(); public DbSet<Member> Members=>Set<Member>(); public DbSet<Loan> Loans=>Set<Loan>(); public DbSet<MembershipPayment> MembershipPayments=>Set<MembershipPayment>(); public DbSet<Setting> Settings=>Set<Setting>(); protected override void OnConfiguring(DbContextOptionsBuilder o){var dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Data");Directory.CreateDirectory(dir);var file=Path.Combine(dir,"LibraryManager.db");o.UseSqlite($"Data Source={file}");} protected override void OnModelCreating(ModelBuilder b){b.Entity<Member>().HasIndex(x=>x.NationalId).IsUnique();b.Entity<Setting>().HasIndex(x=>x.Key).IsUnique();b.Entity<Loan>().HasOne(x=>x.Book).WithMany().HasForeignKey(x=>x.BookId).OnDelete(DeleteBehavior.Restrict);b.Entity<Loan>().HasOne(x=>x.Member).WithMany(x=>x.Loans).HasForeignKey(x=>x.MemberId).OnDelete(DeleteBehavior.Restrict);b.Entity<MembershipPayment>().HasOne(x=>x.Member).WithMany().HasForeignKey(x=>x.MemberId).OnDelete(DeleteBehavior.Cascade);b.Entity<Book>().Property(x=>x.Price).HasPrecision(18,2);b.Entity<Loan>().Property(x=>x.FineAmount).HasPrecision(18,2);b.Entity<MembershipPayment>().Property(x=>x.Amount).HasPrecision(18,2);} }